class Ambassador:
    """Local proxy the app always talks to; the real backend can move."""
    def __init__(self, backend_host):
        self.backend_host = backend_host

    def forward(self, query):
        return f"{query} -> routed to {self.backend_host}"


class LegacyApp:
    """Only ever calls 'localhost:5432', never the real database host."""
    def __init__(self, ambassador):
        self.ambassador = ambassador

    def run_query(self, sql):
        return self.ambassador.forward(sql)


ambassador = Ambassador(backend_host="db-old.internal:5432")
app = LegacyApp(ambassador)
print(app.run_query("SELECT 1"))

# Database migrates to a new host; only the ambassador config changes
ambassador.backend_host = "db-new.internal:5432"
print(app.run_query("SELECT 1"))
